namespace DocSummary.Models;

public class SummarizeRequest
{
    public required string DocumentText { get; set; }
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public required string Summary { get; set; }
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

namespace DocSummary.Services;

public interface IDocumentSummaryService
{
    string Summarize(string documentText, int maxSentences);
}

using System.Text.RegularExpressions;

namespace DocSummary.Services;

public partial class ExtractiveSummaryService : IDocumentSummaryService
{
    public string Summarize(string documentText, int maxSentences)
    {
        var sentences = SplitIntoSentences(documentText);

        if (sentences.Count <= maxSentences)
            return string.Join(" ", sentences);

        var scored = sentences
            .Select((sentence, index) => new { Sentence = sentence, Score = ScoreSentence(sentence, sentences, index) })
            .OrderByDescending(s => s.Score)
            .Take(maxSentences)
            .OrderBy(s => sentences.IndexOf(s.Sentence))
            .Select(s => s.Sentence);

        return string.Join(" ", scored);
    }

    private static List<string> SplitIntoSentences(string text)
    {
        return SentenceRegex().Matches(text)
            .Select(m => m.Value.Trim())
            .Where(s => s.Length > 0)
            .ToList();
    }

    private static double ScoreSentence(string sentence, List<string> allSentences, int position)
    {
        var words = GetWords(sentence);
        var allWords = allSentences.SelectMany(GetWords).ToList();

        // Word frequency scoring
        var wordFrequency = allWords
            .GroupBy(w => w, StringComparer.OrdinalIgnoreCase)
            .ToDictionary(g => g.Key, g => g.Count(), StringComparer.OrdinalIgnoreCase);

        double frequencyScore = words.Sum(w => wordFrequency.GetValueOrDefault(w, 0)) / (double)Math.Max(words.Count, 1);

        // Position bias: earlier sentences score higher
        double positionScore = 1.0 / (position + 1);

        // Length preference: moderate-length sentences are preferred
        double lengthScore = words.Count >= 5 && words.Count <= 30 ? 1.0 : 0.5;

        return frequencyScore + positionScore * 2 + lengthScore;
    }

    private static List<string> GetWords(string text)
    {
        return WordRegex().Matches(text)
            .Select(m => m.Value.ToLowerInvariant())
            .Where(w => w.Length > 2)
            .ToList();
    }

    [GeneratedRegex(@"[^.!?]*[.!?]+", RegexOptions.Compiled)]
    private static partial Regex SentenceRegex();

    [GeneratedRegex(@"\w+", RegexOptions.Compiled)]
    private static partial Regex WordRegex();
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummaryController(IDocumentSummaryService summaryService) : ControllerBase
{
    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.DocumentText))
            return BadRequest("DocumentText cannot be empty.");

        var summary = summaryService.Summarize(request.DocumentText, request.MaxSentences);

        return Ok(new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = request.DocumentText.Length,
            SummaryLength = summary.Length
        });
    }
}

