+        double frequencyScore = words.Sum(w => wordFrequency.GetValueOrDefault(w, 0)) / (double)Math.Max(words.Count, 1);
+
+        // Position bias: earlier sentences score higher
+        double positionScore = 1.0 / (position + 1);
+
+        // Length preference: moderate-length sentences are preferred
+        double lengthScore = words.Count >= 5 && words.Count <= 30 ? 1.0 : 0.5;
+
+        return frequencyScore + positionScore * 2 + lengthScore;
+    }
+
+    private static List<string> GetWords(string text)
+    {
+        return WordRegex().Matches(text)
+            .Select(m => m.Value.ToLowerInvariant())
+            .Where(w => w.Length > 2)
+            .ToList();
+    }
+
+    [GeneratedRegex(@"[^.!?]*[.!?]+", RegexOptions.Compiled)]
+    private static partial Regex SentenceRegex();
+
+    [GeneratedRegex(@"\w+", RegexOptions.Compiled)]
